# shellcheck shell=sh

# lib.sh: shared discovery helper for the util/ router and its completion.
# Sourced by both dispatch.sh (exec'd as a separate process) and
# completions.sh (sourced into the interactive shell), so this file must have
# no side effects when sourced -- no top-level exec, exit, or complete.
#
# CC0: This work has been marked as dedicated to the public domain.
# https://creativecommons.org/publicdomain/zero/1.0/

# infrastructure files that are not subcommands
# >>> shguard modes=source (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/lib.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  source) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: source; pipe callers set SHGUARD_MODE=pipe)\n' 'lib.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
_util_infra="dispatch lib completions"

# _util_commands <dir>: list routable command names findable in <dir> --
# public util/*.sh (excluding infrastructure), then any private overlay
# (<dir>/../private/util/*.sh). The one discovery operation shared by
# dispatch.sh's listing and completions.sh's completion, so both stay in
# sync on overlay precedence, infrastructure exclusion, and .sh resolution.
# Output is sorted and de-duplicated (LC_ALL=C sort -u) across public+private.
_util_commands () {
	_util_commands_raw "$1" | LC_ALL=C sort -u
}

_util_commands_raw () {
	local dir="$1" priv f name
	priv="$dir/../private/util"

	for f in "$dir"/*.sh; do
		[ -e "$f" ] || continue
		name=$( basename "$f" .sh )
		case " $_util_infra " in
			*" $name "*) continue ;;
		esac
		echo "$name"
	done

	if [ -d "$priv" ]; then
		for f in "$priv"/*.sh; do
			[ -e "$f" ] || continue
			basename "$f" .sh
		done
	fi
}
